// Normalize incoming chat message and stage test scenarios
const incoming = $input.item.json || {};

return {
  json: {
    userId: incoming.userId || "USER-EMP-4019",
    message: incoming.message || "What is our travel reimbursement policy for domestic flights?",
    channel: incoming.channel || "SLACK_DIRECT",
    timestamp: new Date().toISOString(),
    // Scenario override helper for direct 1-click test evaluation
    testScenario: incoming.testScenario || null,
    managerApprovalAction: incoming.managerApprovalAction !== undefined ? incoming.managerApprovalAction : "APPROVE"
  }
};

// Phase 1: Authenticate User & Validate RBAC Role against PostgreSQL Directory
const item = $input.item.json;
const userId = item.userId;

// Simulated Enterprise User Directory (mirrors PostgreSQL enterprise_users table)
const userDirectory = {
  "USER-EMP-4019": {
    userId: "USER-EMP-4019",
    name: "Kavita Reddy",
    email: "kavita.r@enterprise.com",
    role: "EMPLOYEE",
    department: "Engineering",
    managerEmail: "vikram.singh@enterprise.com",
    annualLeaveBalance: 14
  },
  "USER-EMP-9912": {
    userId: "USER-EMP-9912",
    name: "Rahul Verma",
    email: "rahul.v@enterprise.com",
    role: "EMPLOYEE",
    department: "Operations",
    managerEmail: "vikram.singh@enterprise.com",
    annualLeaveBalance: 2
  },
  "USER-MGR-2010": {
    userId: "USER-MGR-2010",
    name: "Vikram Singh",
    email: "vikram.singh@enterprise.com",
    role: "MANAGER",
    department: "Engineering",
    managerEmail: "priya.sharma@enterprise.com",
    annualLeaveBalance: 22
  },
  "USER-EXEC-1001": {
    userId: "USER-EXEC-1001",
    name: "Priya Sharma",
    email: "priya.sharma@enterprise.com",
    role: "EXECUTIVE",
    department: "Executive Leadership",
    managerEmail: "board@enterprise.com",
    annualLeaveBalance: 30
  }
};

const user = userDirectory[userId] || {
  userId: userId,
  name: "Guest Employee",
  email: `${userId.toLowerCase()}@enterprise.com`,
  role: "EMPLOYEE",
  department: "General",
  managerEmail: "support@enterprise.com",
  annualLeaveBalance: 10
};

// Define accessible RBAC tiers for Knowledge RAG
let allowedTiers = ["EMPLOYEE"];
if (user.role === "MANAGER") {
  allowedTiers = ["EMPLOYEE", "MANAGER"];
} else if (user.role === "EXECUTIVE") {
  allowedTiers = ["EMPLOYEE", "MANAGER", "EXECUTIVE"];
}

return {
  json: {
    ...item,
    authenticatedUser: user,
    rbacContext: {
      role: user.role,
      department: user.department,
      allowedTiers: allowedTiers,
      sessionToken: `SESSION-SEC-${Math.random().toString(36).substring(2, 9).toUpperCase()}`,
      verifiedAt: new Date().toISOString()
    }
  }
};

// Phase 2: n8n AI Agent Node Orchestrator (Intent Recognition & Tool Decision)
const item = $input.item.json;
const prompt = (item.message || "").toLowerCase();
const scenario = item.testScenario;

let selectedTool = "QUERY_KNOWLEDGE_BASE";
let intentReasoning = "";

if (scenario === "TC-01" || prompt.includes("travel") || prompt.includes("flight") || prompt.includes("policy") || prompt.includes("reimbursement") || prompt.includes("bonus") || prompt.includes("compensation")) {
  selectedTool = "QUERY_KNOWLEDGE_BASE";
  intentReasoning = "User is requesting company policy or standard operating procedure information. Dispatching RBAC vector search.";
} else if (scenario === "TC-03" || scenario === "TC-04" || prompt.includes("leave") || prompt.includes("vacation") || prompt.includes("time off")) {
  selectedTool = "SUBMIT_LEAVE_REQUEST";
  intentReasoning = "User is requesting leave days deduction. Routing to Leave Management and Manager Approval gate.";
} else if (scenario === "TC-05" || prompt.includes("vpn") || prompt.includes("ticket") || prompt.includes("error") || prompt.includes("laptop") || prompt.includes("support")) {
  selectedTool = "CREATE_IT_TICKET";
  intentReasoning = "User reported a technical infrastructure malfunction. Dispatching IT Support Requisition tool.";
} else if (prompt.includes("crm") || prompt.includes("client") || prompt.includes("contract") || prompt.includes("mrr") || prompt.includes("acme") || prompt.includes("globex")) {
  selectedTool = "LOOKUP_CRM_CLIENT";
  intentReasoning = "User requested customer CRM account health summary. Querying PostgreSQL Client Ledger.";
}

return {
  json: {
    ...item,
    aiOrchestrator: {
      model: "gpt-4o",
      selectedTool: selectedTool,
      intentReasoning: intentReasoning,
      decidedAt: new Date().toISOString()
    }
  }
};

// Phase 3: Tool 1 - RBAC-Grounded Knowledge Vector Search (pgvector Simulation)
const item = $input.item.json;
const prompt = (item.message || "").toLowerCase();
const userRole = item.authenticatedUser.role;
const allowedTiers = item.rbacContext.allowedTiers;

// Knowledge base chunks mirroring PostgreSQL enterprise_knowledge
const knowledgeBase = [
  {
    chunkId: "c1-travel-policy",
    documentTitle: "Corporate Travel Policy 2026",
    sectionTitle: "Domestic Flight Reimbursement",
    requiredRoleTier: "EMPLOYEE",
    content: "Employees traveling on company business are authorized for economy class commercial domestic flights booked at least 14 days in advance. Meals are reimbursed up to $75 USD per diem with valid itemized receipts. Ground transit via Uber/Lyft is covered for airport transfers and client meetings.",
    citation: "Source: SOP-TRAVEL-2026-V2 (Section 4.1)"
  },
  {
    chunkId: "c2-exec-comp",
    documentTitle: "Executive Compensation Covenant",
    sectionTitle: "C-Suite Bonus Tiers & Equity Acceleration",
    requiredRoleTier: "EXECUTIVE",
    content: "CONFIDENTIAL RESTRICTED: Executive leadership bonus compensation tiers are evaluated on annual EBITDA benchmarks: Tier 1 (100% target achievement) yields a 45% base bonus multiplier; Tier 2 (125% target) triggers a 75% multiplier with 25% accelerated vesting on Class A preferred equity shares.",
    citation: "Source: EXEC-CONFIDENTIAL-COMP-2026 (Section 9.4)"
  },
  {
    chunkId: "c3-vpn-sop",
    documentTitle: "IT Remote Access Standard Operating Procedure",
    sectionTitle: "VPN Client Configuration & Error 789",
    requiredRoleTier: "EMPLOYEE",
    content: "Remote staff must authenticate via Enterprise GlobalProtect VPN using FIDO2 keys. Error 789 indicates an IPsec security negotiation timeout. Users should flush DNS via `ipconfig /flushdns` or submit an urgent IT ticket.",
    citation: "Source: SOP-SEC-NET-789 (Section 2.3)"
  }
];

// Determine matching document
let targetChunk = null;
if (prompt.includes("bonus") || prompt.includes("compensation") || prompt.includes("equity")) {
  targetChunk = knowledgeBase.find(c => c.chunkId === "c2-exec-comp");
} else if (prompt.includes("vpn") || prompt.includes("789")) {
  targetChunk = knowledgeBase.find(c => c.chunkId === "c3-vpn-sop");
} else {
  targetChunk = knowledgeBase.find(c => c.chunkId === "c1-travel-policy");
}

let toolResult = {};
if (targetChunk) {
  // Enforce strict RBAC Gate
  const isAuthorized = allowedTiers.includes(targetChunk.requiredRoleTier);
  if (!isAuthorized) {
    toolResult = {
      rbacStatus: "ACCESS_DENIED_INSUFFICIENT_CLEARANCE",
      requiredTier: targetChunk.requiredRoleTier,
      userRole: userRole,
      groundedAnswer: `Security Alert: Access to "${targetChunk.documentTitle}" requires [${targetChunk.requiredRoleTier}] clearance. Your current verified role is [${userRole}]. Access has been denied and logged to the security audit trail.`,
      citation: "N/A - RESTRICTED_CONFIDENTIAL"
    };
  } else {
    toolResult = {
      rbacStatus: "ACCESS_GRANTED_AUTHORIZED",
      documentTitle: targetChunk.documentTitle,
      sectionTitle: targetChunk.sectionTitle,
      requiredTier: targetChunk.requiredRoleTier,
      content: targetChunk.content,
      citation: targetChunk.citation,
      groundedAnswer: `${targetChunk.content}\n\n**Verified Reference:** ${targetChunk.citation}`
    };
  }
}

return {
  json: {
    ...item,
    toolExecution: {
      toolName: "query_knowledge_base",
      result: toolResult,
      executedAt: new Date().toISOString()
    }
  }
};

// Phase 4: Tool 2 - Leave Request Submission & Balance Check
const item = $input.item.json;
const user = item.authenticatedUser;
const prompt = item.message || "";

// Extract requested days from message or scenario defaults
let requestedDays = 3;
const daysMatch = prompt.match(/(\d+)\s*(day|days)/i);
if (daysMatch) {
  requestedDays = parseInt(daysMatch[1], 10);
}

const currentBalance = user.annualLeaveBalance;
const hasSufficientBalance = currentBalance >= requestedDays;

return {
  json: {
    ...item,
    leaveCalculation: {
      requestedDays: requestedDays,
      currentBalance: currentBalance,
      hasSufficientBalance: hasSufficientBalance,
      startDate: "2026-11-23",
      endDate: "2026-11-25",
      reason: "Medical / Annual Personal Leave Request"
    }
  }
};

// Phase 8: Manager Human Approval Gate (Slack / Form Simulation)
const item = $input.item.json;
const leave = item.leaveCalculation;
const user = item.authenticatedUser;
const managerAction = item.managerApprovalAction || "APPROVE";

const requestId = `LEAVE-REQ-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

let finalStatus = "";
let updatedBalance = user.annualLeaveBalance;
let responseMessage = "";

if (managerAction === "APPROVE") {
  finalStatus = "APPROVED";
  updatedBalance = user.annualLeaveBalance - leave.requestedDays;
  responseMessage = `Your leave request for ${leave.requestedDays} business days (${leave.startDate} to ${leave.endDate}) has been APPROVED by your manager (${user.managerEmail}). Your updated annual leave balance is now ${updatedBalance} days.`;
} else {
  finalStatus = "REJECTED";
  responseMessage = `Your leave request for ${leave.requestedDays} business days was REJECTED by your manager (${user.managerEmail}). Your annual leave balance remains ${user.annualLeaveBalance} days.`;
}

return {
  json: {
    ...item,
    toolExecution: {
      toolName: "submit_leave_request",
      result: {
        requestId: requestId,
        status: finalStatus,
        managerEmail: user.managerEmail,
        deductedDays: managerAction === "APPROVE" ? leave.requestedDays : 0,
        newBalance: updatedBalance,
        groundedAnswer: responseMessage
      },
      executedAt: new Date().toISOString()
    }
  }
};

// Insufficient Leave Balance Rejection Notice
const item = $input.item.json;
const leave = item.leaveCalculation;
const user = item.authenticatedUser;

return {
  json: {
    ...item,
    toolExecution: {
      toolName: "submit_leave_request",
      result: {
        status: "DECLINED_INSUFFICIENT_BALANCE",
        requestedDays: leave.requestedDays,
        currentBalance: user.annualLeaveBalance,
        groundedAnswer: `Leave Request Failed: You requested ${leave.requestedDays} days of leave, but your current annual leave balance is only ${user.annualLeaveBalance} days. Please adjust your dates or contact HR Operations.`
      },
      executedAt: new Date().toISOString()
    }
  }
};

// Phase 5: Tool 3 - IT Support Ticket Creation
const item = $input.item.json;
const prompt = item.message || "";
const user = item.authenticatedUser;

const ticketId = "IT-TICK-8841";
let category = "Network & VPN Services";
let urgency = "HIGH";

if (prompt.toLowerCase().includes("vpn") || prompt.toLowerCase().includes("789")) {
  category = "GlobalProtect VPN Gateway Timeout";
  urgency = "HIGH";
}

return {
  json: {
    ...item,
    toolExecution: {
      toolName: "create_it_ticket",
      result: {
        ticketId: ticketId,
        category: category,
        urgency: urgency,
        submittedBy: user.userId,
        status: "OPEN_ASSIGNED_TO_SECOPS",
        groundedAnswer: `IT Ticket #${ticketId} has been successfully created with [${urgency}] priority for category "${category}". Our Network Engineering on-call team has been paged. You will receive updates at ${user.email}.`
      },
      executedAt: new Date().toISOString()
    }
  }
};

// Phase 6: Tool 4 - CRM Client Health Lookup (PostgreSQL Client Ledger Simulation)
const item = $input.item.json;
const prompt = (item.message || "").toLowerCase();

const crmDirectory = {
  "acme": {
    clientId: "CRM-ACME-01",
    clientName: "Acme Corporation",
    contractStatus: "ACTIVE",
    activeMRR: 45000.00,
    renewalDate: "2027-04-15",
    accountManager: "Vikram Singh",
    tier: "ENTERPRISE_PLATINUM"
  },
  "globex": {
    clientId: "CRM-GLOBEX-02",
    clientName: "Globex Systems",
    contractStatus: "EXPIRING_SOON",
    activeMRR: 18500.00,
    renewalDate: "2026-12-31",
    accountManager: "Vikram Singh",
    tier: "ENTERPRISE_GOLD"
  }
};

let client = crmDirectory["acme"];
if (prompt.includes("globex")) {
  client = crmDirectory["globex"];
}

return {
  json: {
    ...item,
    toolExecution: {
      toolName: "lookup_crm_client",
      result: {
        ...client,
        groundedAnswer: `**CRM Account Health:** **${client.clientName}**\n• **Status:** ${client.contractStatus}\n• **Active MRR:** $${client.activeMRR.toLocaleString('en-US', { minimumFractionDigits: 2 })} USD\n• **Next Renewal:** ${client.renewalDate}\n• **Account Lead:** ${client.accountManager} (${client.tier})`
      },
      executedAt: new Date().toISOString()
    }
  }
};

// Phase 10: Persist Full Agent Execution & Audit Telemetry in PostgreSQL
const item = $input.item.json;
const user = item.authenticatedUser;
const tool = item.toolExecution;

const auditRecord = {
  auditId: `AUDIT-UUID-${Math.random().toString(36).substring(2, 9).toUpperCase()}`,
  userId: user.userId,
  userRole: user.role,
  userPrompt: item.message,
  toolsInvoked: [
    {
      toolName: tool.toolName,
      status: tool.result.status || tool.result.rbacStatus || "SUCCESS",
      executedAt: tool.executedAt
    }
  ],
  agentResponse: tool.result.groundedAnswer,
  latencyMs: Math.floor(Math.random() * 80) + 120,
  targetPostgresTable: "agent_execution_audit",
  persistedAt: new Date().toISOString()
};

return {
  json: {
    finalDeliveryStatus: "CONVERSATION_DELIVERED_AND_AUDITED",
    auditLedgerEntry: auditRecord,
    chatResponse: tool.result.groundedAnswer
  }
};
